{"path": "tmp_check.py", "content": "import sqlparse
from sqlparse import sql

tests = [
    "SELECT * FROM foo WHERE x = NULL",
    "SELECT * FROM foo WHERE x = 1.5",
    "SELECT * FROM foo WHERE x = (SELECT 1)",
    "SELECT * FROM foo WHERE x = 'bar'",
    "SELECT * FROM foo WHERE x = y",
    "SELECT * FROM foo WHERE x = 5",
]

for t in tests:
    stmt = sqlparse.parse(t)[0]
    cmp_tokens = [tok for tok in stmt.flatten()]
    def find_comparison(tl):
        for tok in tl.tokens:
            if isinstance(tok, sql.Comparison):
                return tok
            if tok.is_group:
                r = find_comparison(tok)
                if r:
                    return r
        return None
    c = find_comparison(stmt)
    print(t, '->', repr(c.left), repr(c.right))
"}

